CREATE TYPE "ReportStatus" AS ENUM ('SUBMITTED', 'PROCESSING', 'RESOLVED', 'REJECTED');
CREATE TABLE "Device" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "name" TEXT NOT NULL, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Device_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Report" ("id" TEXT NOT NULL, "reporterId" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetId" TEXT NOT NULL, "reason" TEXT NOT NULL, "status" "ReportStatus" NOT NULL DEFAULT 'SUBMITTED', "resolution" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Report_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Device_fingerprint_key" ON "Device"("fingerprint");
ALTER TABLE "Device" ADD CONSTRAINT "Device_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Report" ADD CONSTRAINT "Report_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
